param([string]$ProjectRoot = (Split-Path -Parent $PSScriptRoot))

$ErrorActionPreference='Stop'
if([Threading.Thread]::CurrentThread.ApartmentState-ne[Threading.ApartmentState]::STA){throw'Run with powershell.exe -STA.'}
$halcon='C:\Program Files\MVTec\HALCON-20.11-Progress';$env:PATH=(Join-Path $halcon 'bin\x64-win64')+';'+$env:PATH
Add-Type -AssemblyName PresentationFramework
[Reflection.Assembly]::LoadFrom((Join-Path $halcon 'bin\dotnet35\halcondotnet.dll'))|Out-Null
$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$c,[string]$m){if(-not $c){throw $m}}
function Pump([int]$ms){$f=New-Object Windows.Threading.DispatcherFrame;$t=New-Object Windows.Threading.DispatcherTimer;$t.Interval=[TimeSpan]::FromMilliseconds($ms);$t.Add_Tick({$t.Stop();$f.Continue=$false});$t.Start();[Windows.Threading.Dispatcher]::PushFrame($f)}
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$lineType=$assembly.GetType('HalconWinFormsDemo.Models.VmLine2D',$true)
$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public';$static=[Reflection.BindingFlags]'Static,Public'
$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s71-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
$app=[Windows.Application]::Current;$ownsApp=$null-eq$app;if($ownsApp){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown};$window.ShowInTaskbar=$false;$window.Left=-10000;$window.Show();Pump 180
function F([string]$n){$v=$main.GetField($n,$all).GetValue($window);Write-Output -NoEnumerate $v}
function M([string]$n,[object[]]$p=@()){try{$main.GetMethod($n,$private).Invoke($window,$p)}catch{$e=$_.Exception;while($e.InnerException){$e=$e.InnerException};throw($n+': '+$e.Message)}}
function K([string]$n){[Enum]::Parse($kindType,$n)}
function Tool([string]$k,[string]$n){M 'CreateFlowTool' ([object[]]@((K $k),$n,$true,$null))}
function Run($t){M 'ExecuteFlowTool' ([object[]]@($t,'S71 smoke'))}
function Out($t,[string]$p){$a=[object[]]@($p,$null);if(-not$t.GetType().GetMethod('TryGetOutputValue').Invoke($t,$a)){throw"Missing output $p"};$a[1]}
function Has($t,[string]$p){$a=[object[]]@($p,$null);[bool]$t.GetType().GetMethod('TryGetOutputValue').Invoke($t,$a)}
function Line([double]$r1,[double]$c1,[double]$r2,[double]$c2,[string]$ctx){$lineType.GetMethod('CreateImagePixel',$static).Invoke($null,[object[]]@($r1,$c1,$r2,$c2,$ctx))}
function SelectTools([object[]]$tools){(F 'FlowToolList').SelectedItems.Clear();foreach($tool in $tools){(F 'FlowToolList').SelectedItems.Add($tool)}}
try{
  Assert ((F 'toolCatalog').Count-eq70 -and (F 'toolCatalog').Count-eq[Enum]::GetValues($kindType).Count) 'S71 compatibility catalog mismatch after S75.'
  Assert ((F 'DeveloperToolbarPanel').Children.Count-eq7) 'S71 added a permanent top command.'
  $visibleFilters=@((F 'ToolCatalogModePanel').Children|Where-Object {$_.Visibility.ToString()-eq'Visible'});Assert ($visibleFilters.Count-eq1 -and $visibleFilters[0].Name-eq'ToolCatalogAllButton') 'Left toolbox exposes more than the single Classification entry.'
  Assert ((F 'ToolCatalogList').Visibility.ToString()-eq'Visible' -and (F 'ToolSnippetCatalogList').Visibility.ToString()-eq'Collapsed') 'Default toolbox is not the full categorized tool catalog.'

  # A: create a real snippet, discover it from the single Classification menu, preview and insert through the reused S70 core.
  $flow=F 'flowTools';M 'DisposeFlowTools'|Out-Null;$flow.Clear();$pa=Tool 'PointSetGeometryStatistics' 'A Source';$pb=Tool 'PointSetGeometryStatistics' 'B Source';$pair=Tool 'PointPairLineConstructionMeasurement' 'Construct Line';$judge=Tool 'NumericJudge' 'Distance Judge';foreach($t in @($pa,$pb,$pair,$judge)){$flow.Add($t)}
  $pair.SetInputBinding('PointA',$pa.ToolId,'Centroid');$pair.SetInputBinding('PointB',$pb.ToolId,'Centroid');$judge.SetInputBinding('Value',$pair.ToolId,'Distance');$judge.InputToolId=$pair.ToolId;$judge.InputPortName='Distance'
  M 'OpenFlowSnippetLibraryButton_Click' ([object[]]@($null,[Windows.RoutedEventArgs]::new()))|Out-Null;SelectTools @($pair,$judge);(F 'FlowSnippetNameTextBox').Text='Line QA Chain';M 'SaveSelectedFlowSnippetButton_Click' ([object[]]@($null,[Windows.RoutedEventArgs]::new()))|Out-Null;Assert ((F 'flowSnippetLibraryS70').Snippets.Count-eq1) 'Fixture snippet save failed.';M 'CloseFlowSnippetLibraryButton_Click' ([object[]]@($null,[Windows.RoutedEventArgs]::new()))|Out-Null
  M 'ToolCatalogShowSnippetsMenuItem_Click' ([object[]]@($null,[Windows.RoutedEventArgs]::new()))|Out-Null
  Assert ((F 'ToolCatalogList').Visibility.ToString()-eq'Collapsed' -and (F 'ToolSnippetCatalogList').Visibility.ToString()-eq'Visible' -and (F 'toolboxSnippetItemsS71').Count-eq1) 'Classification menu did not switch to on-demand snippets.'
  $previewPurpose=(F 'ToolCapabilityPurposeText').Text;$previewInput=(F 'ToolCapabilityInputText').Text;$previewGraphics=(F 'ToolCapabilityGraphicsText').Text;Write-Output ('S71_SNIPPET_PREVIEW='+$previewPurpose+'|'+$previewInput+'|'+$previewGraphics)
  $previewOk1=[bool]($previewPurpose -match 'Construct Line.*Distance Judge');$previewOk2=[bool]($previewInput -match 'PointA:Point2D');$previewOk3=$previewGraphics.Length -gt 12;Assert ($previewOk1 -and $previewOk2 -and $previewOk3) 'Snippet order/internal/external contract preview is incomplete.'
  M 'DisposeFlowTools'|Out-Null;$flow.Clear();$anchor=Tool 'ImageSource' 'Anchor';$flow.Add($anchor);(F 'FlowToolList').SelectedItem=$anchor;$before=$flow.Count;M 'InsertSelectedToolboxSnippetS71' ([object[]]@($true))|Out-Null
  Assert ($flow.Count-eq$before+2) 'Left snippet insertion did not reuse the two-tool template.'
  $copies=@($flow|Select-Object -Last 2);Assert ($copies[1].GetInputBinding('Value').SourceToolId-eq$copies[0].ToolId) 'Snippet internal binding was not remapped.'
  Assert ((F 'FlowConnectionIssuePanel').Visibility.ToString()-eq'Visible' -and (F 'connectionIssuesS69').Count-ge2 -and (F 'FlowConnectionIssueSummaryText').Text-match'S68') 'Unresolved external inputs did not become visible source-supplement tasks.'
  $firstBlocking=@((F 'connectionIssuesS69')|Where-Object IsBlocking)[0];(F 'FlowConnectionIssueListBox').SelectedItem=$firstBlocking;M 'OpenConnectionIssueSourceButton_Click' ([object[]]@($null,[Windows.RoutedEventArgs]::new()))|Out-Null;Assert ((F 'ToolInputSourceContextBorder').Visibility.ToString()-eq'Visible') 'Snippet unresolved task did not hand off to S68.';M 'ExitInputSourceContextS68' ([object[]]@($false))|Out-Null
  M 'UndoFlowEditButton_Click' ([object[]]@($null,$null))|Out-Null;Assert ($flow.Count-eq1) 'One undo did not remove the inserted snippet.';M 'RedoFlowEditButton_Click' ([object[]]@($null,$null))|Out-Null;Assert ($flow.Count-eq3) 'Redo did not restore the inserted snippet.'
  M 'RefreshFlowGraphLayout'|Out-Null;$ordered=@($flow|Sort-Object GraphY);Assert (($ordered|Select-Object -ExpandProperty GraphX|Select-Object -Unique).Count-eq1 -and $ordered[0].GraphY-lt$ordered[1].GraphY -and $ordered[1].GraphY-lt$ordered[2].GraphY -and $ordered[0].GraphHeight-le74.1) 'Automatic graph is not compact top-to-bottom.'
  $activityTool=$flow[1];(F 'FlowToolList').SelectedItem=$activityTool;M 'OpenFlowStepActivityS71' ([object[]]@($activityTool))|Out-Null;Assert ((F 'FlowStepActivityPanel').Visibility.ToString()-eq'Visible' -and (F 'FlowStepActivityTitleText').Text-match'Construct Line' -and (F 'FlowStepCommunicationTextBox').Text.Length-gt10) 'Per-step log/communication task page did not open.';M 'CloseFlowStepActivityButton_Click' ([object[]]@($null,[Windows.RoutedEventArgs]::new()))|Out-Null
  M 'ToolCatalogShowAllMenuItem_Click' ([object[]]@($null,[Windows.RoutedEventArgs]::new()))|Out-Null;Assert ((F 'ToolCatalogList').Visibility.ToString()-eq'Visible' -and -not [bool](F 'toolboxSnippetModeS71')) 'Classification menu did not return to full tools.'

  # B: HALCON Line2D + Line2D relation, finite point downstream, numbers, recipe/copy/lifecycle and failure semantics.
  M 'DisposeFlowTools'|Out-Null;$flow.Clear();$la=Tool 'XldLineFitting' 'Typed Line A';$lb=Tool 'PointPairLineConstructionMeasurement' 'Typed Line B';$rel=Tool 'TypedLineLineRelationMeasurement' 'Typed Line Relation';$pointDistance=Tool 'PointToLineDistanceMeasurement' 'Intersection To Line';$numJudge=Tool 'NumericJudge' 'Angle Judge';foreach($t in @($la,$lb,$rel,$pointDistance,$numJudge)){$flow.Add($t)}
  $rel.SetInputBinding('LineA',$la.ToolId,'MainLine');$rel.SetInputBinding('LineB',$lb.ToolId,'MainLine');$pointDistance.SetInputBinding('Point',$rel.ToolId,'IntersectionPoint');$pointDistance.SetInputBinding('Line',$la.ToolId,'MainLine');$numJudge.SetInputBinding('Value',$rel.ToolId,'AcuteAngle');$numJudge.InputToolId=$rel.ToolId;$numJudge.InputPortName='AcuteAngle';$numJudge.NumericOperator='BetweenInclusive';$numJudge.NumericLowerLimit=89.9;$numJudge.NumericUpperLimit=90.1
  $ctx='S71.Image';$la.SetOutputValue('MainLine',(Line 5 0 5 10 $ctx));$la.ResultCode='OK';$lb.SetOutputValue('MainLine',(Line 0 5 10 5 $ctx));$lb.ResultCode='OK';$result=Run $rel
  $relation=[string](Out $rel 'Relation');$parallel=[bool](Out $rel 'IsParallel');$acute=[double](Out $rel 'AcuteAngle');Write-Output ('S71_INTERSECTION='+$result.ResultCode+'|'+$relation+'|'+$parallel+'|'+(Out $rel 'SignedAngle')+'|'+$acute)
  $f1=$result.ResultCode -eq 'OK';$f2=$relation.Length -gt 0;$f3=-not $parallel;$f4=[Math]::Abs($acute - 90) -lt 0.0001;Assert ($f1 -and $f2 -and $f3 -and $f4) 'HALCON intersecting Line2D semantics failed.'
  $point=Out $rel 'IntersectionPoint';$intersectionXld=Out $rel 'XLD';Assert (([Math]::Abs($point.Row - 5) -lt 0.0001) -and ([Math]::Abs($point.Column - 5) -lt 0.0001) -and ($intersectionXld.ObjectCount -eq 3)) 'Finite typed intersection point or managed XLD is wrong.'
  $pointResult=Run $pointDistance;$pointDistanceValue=[double](Out $pointDistance 'Distance');$judgeResult=Run $numJudge;Assert (($pointResult.ResultCode -eq 'OK') -and ([Math]::Abs($pointDistanceValue) -lt 0.0001) -and ($judgeResult.ResultCode -eq 'OK')) 'IntersectionPoint or acute-angle downstream chain failed.'
  $old=Out $rel 'XLD';$lb.SetOutputValue('MainLine',(Line 8 0 8 10 $ctx));$lb.ResultCode='OK';$result=Run $rel;$parallelFlag=[bool](Out $rel 'IsParallel');$coincidentFlag=[bool](Out $rel 'IsCoincident');$parallelDistance=[double](Out $rel 'ParallelDistance');$parallelXld=Out $rel 'XLD';Assert (($result.ResultCode -eq 'OK') -and $parallelFlag -and (-not $coincidentFlag) -and ([Math]::Abs($parallelDistance - 3) -lt 0.0001) -and (-not (Has $rel 'IntersectionPoint')) -and $old.IsDisposed -and ($parallelXld.ObjectCount -eq 2)) 'Parallel semantics, stale point clearing, or XLD lifecycle failed.'
  $lb.SetOutputValue('MainLine',(Line 5 2 5 8 $ctx));$lb.ResultCode='OK';Run $rel|Out-Null;$coincident=[bool](Out $rel 'IsCoincident');Assert ($coincident -and (-not (Has $rel 'IntersectionPoint'))) 'Coincident relation was misrepresented as finite intersection.'
  $lb.SetOutputValue('MainLine',(Line 5.005 0 5.005 10 $ctx));$lb.ResultCode='OK';Run $rel|Out-Null;$nearCoincident=[bool](Out $rel 'IsCoincident');Assert $nearCoincident 'Near-coincident tolerance semantics failed.'
  (F 'FlowToolList').SelectedItem=$rel;M 'LoadDockConfigurationDraft' ([object[]]@($rel))|Out-Null;Assert ((F 'DockTypedLineLineRelationPanel').Visibility.ToString()-eq'Visible' -and (F 'DockLineLineParallelToleranceTextBox').Text.Length-gt0) 'Typed line-line parameters are not in the persistent right dock.'
  M 'RefreshPortDataMonitorS64' ([object[]]@($rel))|Out-Null;Assert (@((F 'portDataMonitorRows')|Where-Object DataType -eq 'Line2D').Count -ge 2) 'I/O monitor did not expose both Line2D inputs.'
  $rel.Parameters.LineLineParallelToleranceDegrees=0.02;$rel.Parameters.LineLineCoincidenceDistanceTolerance=0.03;$rel.Parameters.LineLineOverlayCrossSize=13;$recipe=M 'CaptureRecipe';$saved=$recipe.ToolFlow|Where-Object ToolId -eq $rel.ToolId|Select-Object -First 1;Assert (([Math]::Abs($saved.Parameters.LineLineParallelToleranceDegrees - 0.02) -lt 0.0001) -and ([Math]::Abs($saved.Parameters.LineLineOverlayCrossSize - 13) -lt 0.0001)) 'Recipe lost typed line-line parameters.'
  SelectTools @($la,$lb,$rel);$copiedCount=[int](M 'CopySelectedFlowToolsToClipboard');$pastedCount=[int](M 'PasteFlowToolClipboard' ([object[]]@($flow.Count)));Assert (($copiedCount -eq 3) -and ($pastedCount -eq 3)) 'Typed line-line block copy/paste failed.';$block=@($flow|Select-Object -Last 3);$copyRel=$block|Where-Object {$_.Kind.ToString() -eq 'TypedLineLineRelationMeasurement'}|Select-Object -First 1;Assert (($copyRel.GetInputBinding('LineA').SourceToolId -eq $block[0].ToolId) -and ($copyRel.GetInputBinding('LineB').SourceToolId -eq $block[1].ToolId)) 'Typed line-line copy did not remap both Line2D sources.'
  $rel.SetInputBinding('LineB',$la.ToolId,'MainLine');$failed=$false;try{Run $rel|Out-Null}catch{$failed=$true};Assert $failed 'Same Line2D endpoint was accepted.'
  $rel.SetInputBinding('LineB',$lb.ToolId,'MainLine');$lb.SetOutputValue('MainLine',(Line 0 0 0 0 $ctx));$lb.ResultCode='OK';$failed=$false;try{Run $rel|Out-Null}catch{$failed=$true};Assert $failed 'Degenerate Line2D was accepted.'
  $lb.SetOutputValue('MainLine',(Line ([double]::NaN) 0 10 0 $ctx));$lb.ResultCode='OK';$failed=$false;try{Run $rel|Out-Null}catch{$failed=$true};Assert $failed 'Nonfinite Line2D was accepted.'
  $lb.SetOutputValue('MainLine',(Line 0 5 10 5 'Other.Image'));$lb.ResultCode='OK';$failed=$false;try{Run $rel|Out-Null}catch{$failed=$true};Assert $failed 'Cross-context Line2D was accepted.'
  $lb.SetOutputValue('MainLine',(Line 0 5 10 5 $ctx));$lb.ResultCode='--';$failed=$false;try{Run $rel|Out-Null}catch{$failed=$true};Assert $failed 'Stale/unrun Line2D source was accepted.'
  Write-Output 'S71 single-classification toolbox/snippet discovery-insertion/tasks/S68/undo + compact vertical graph/flexible curves/step activity + HALCON typed Line2D relation/intersection/downstreams/recipe/copy/lifecycle/failures passed; BSB not implemented.'
}finally{$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();if($ownsApp){$app.Shutdown()};if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}}
